-- Production metadata alignment, additive/widening subset only.
-- Oracle DDL implicitly commits. No baseline or business-row writes.
WHENEVER SQLERROR EXIT FAILURE ROLLBACK
WHENEVER OSERROR EXIT FAILURE ROLLBACK
SET DEFINE OFF
SET SERVEROUTPUT ON
ALTER SESSION SET DDL_LOCK_TIMEOUT=5;
DECLARE
  n NUMBER;
BEGIN
  IF SYS_CONTEXT('USERENV','CURRENT_SCHEMA')<>'LIMS_RUNTIME_LOCAL' OR SYS_CONTEXT('USERENV','CON_NAME')<>'FREEPDB1' THEN RAISE_APPLICATION_ERROR(-20100,'Wrong alignment target'); END IF;
  SELECT COUNT(*) INTO n FROM ALL_TAB_COLS WHERE OWNER='LIMS_RUNTIME_LOCAL' AND TABLE_NAME='T_CORE_AT_RECORD_LINE' AND COLUMN_NAME='COLUMN' AND DATA_TYPE='VARCHAR2' AND DATA_LENGTH=60 AND NULLABLE='Y' AND HIDDEN_COLUMN='NO' AND VIRTUAL_COLUMN='NO' AND DATA_PRECISION IS NULL AND DATA_SCALE IS NULL AND DEFAULT_LENGTH IS NULL AND CHAR_USED='B' AND CHAR_LENGTH=60;
  IF n<>1 THEN RAISE_APPLICATION_ERROR(-20101,'Precondition mismatch T_CORE_AT_RECORD_LINE.COLUMN'); END IF;
  SELECT COUNT(*) INTO n FROM ALL_TAB_COLS WHERE OWNER='LIMS_RUNTIME_LOCAL' AND TABLE_NAME='T_CORE_AT_RECORD_LINE' AND COLUMN_NAME='CREATEDBYNAME' AND DATA_TYPE='VARCHAR2' AND DATA_LENGTH=60 AND NULLABLE='Y' AND HIDDEN_COLUMN='NO' AND VIRTUAL_COLUMN='NO' AND DATA_PRECISION IS NULL AND DATA_SCALE IS NULL AND DEFAULT_LENGTH IS NULL AND CHAR_USED='B' AND CHAR_LENGTH=60;
  IF n<>1 THEN RAISE_APPLICATION_ERROR(-20101,'Precondition mismatch T_CORE_AT_RECORD_LINE.CREATEDBYNAME'); END IF;
  SELECT COUNT(*) INTO n FROM ALL_TAB_COLS WHERE OWNER='LIMS_RUNTIME_LOCAL' AND TABLE_NAME='T_CORE_BPMN_COMMENT' AND COLUMN_NAME='COMMENT' AND DATA_TYPE='VARCHAR2' AND DATA_LENGTH=300 AND NULLABLE='Y' AND HIDDEN_COLUMN='NO' AND VIRTUAL_COLUMN='NO' AND DATA_PRECISION IS NULL AND DATA_SCALE IS NULL AND DEFAULT_LENGTH IS NULL AND CHAR_USED='B' AND CHAR_LENGTH=300;
  IF n<>1 THEN RAISE_APPLICATION_ERROR(-20101,'Precondition mismatch T_CORE_BPMN_COMMENT.COMMENT'); END IF;
  SELECT COUNT(*) INTO n FROM ALL_TAB_COLS WHERE OWNER='LIMS_RUNTIME_LOCAL' AND TABLE_NAME='T_CORE_FILE' AND COLUMN_NAME='CREATEDBYNAME' AND DATA_TYPE='VARCHAR2' AND DATA_LENGTH=60 AND NULLABLE='Y' AND HIDDEN_COLUMN='NO' AND VIRTUAL_COLUMN='NO' AND DATA_PRECISION IS NULL AND DATA_SCALE IS NULL AND DEFAULT_LENGTH IS NULL AND CHAR_USED='B' AND CHAR_LENGTH=60;
  IF n<>1 THEN RAISE_APPLICATION_ERROR(-20101,'Precondition mismatch T_CORE_FILE.CREATEDBYNAME'); END IF;
  SELECT COUNT(*) INTO n FROM ALL_TAB_COLS WHERE OWNER='LIMS_RUNTIME_LOCAL' AND TABLE_NAME='T_CORE_FILE' AND COLUMN_NAME='NAME' AND DATA_TYPE='VARCHAR2' AND DATA_LENGTH=258 AND NULLABLE='Y' AND HIDDEN_COLUMN='NO' AND VIRTUAL_COLUMN='NO' AND DATA_PRECISION IS NULL AND DATA_SCALE IS NULL AND DEFAULT_LENGTH IS NULL AND CHAR_USED='B' AND CHAR_LENGTH=258;
  IF n<>1 THEN RAISE_APPLICATION_ERROR(-20101,'Precondition mismatch T_CORE_FILE.NAME'); END IF;
  SELECT COUNT(*) INTO n FROM ALL_TAB_COLS WHERE OWNER='LIMS_RUNTIME_LOCAL' AND TABLE_NAME='T_CORE_FILE' AND COLUMN_NAME='TARGETID' AND DATA_TYPE='VARCHAR2' AND DATA_LENGTH=60 AND NULLABLE='Y' AND HIDDEN_COLUMN='NO' AND VIRTUAL_COLUMN='NO' AND DATA_PRECISION IS NULL AND DATA_SCALE IS NULL AND DEFAULT_LENGTH IS NULL AND CHAR_USED='B' AND CHAR_LENGTH=60;
  IF n<>1 THEN RAISE_APPLICATION_ERROR(-20101,'Precondition mismatch T_CORE_FILE.TARGETID'); END IF;
  SELECT COUNT(*) INTO n FROM ALL_TAB_COLS WHERE OWNER='LIMS_RUNTIME_LOCAL' AND TABLE_NAME='T_EMC_AUDIT_RECORD' AND COLUMN_NAME='COMMENTS' AND DATA_TYPE='VARCHAR2' AND DATA_LENGTH=600 AND NULLABLE='Y' AND HIDDEN_COLUMN='NO' AND VIRTUAL_COLUMN='NO' AND DATA_PRECISION IS NULL AND DATA_SCALE IS NULL AND DEFAULT_LENGTH IS NULL AND CHAR_USED='B' AND CHAR_LENGTH=600;
  IF n<>1 THEN RAISE_APPLICATION_ERROR(-20101,'Precondition mismatch T_EMC_AUDIT_RECORD.COMMENTS'); END IF;
  SELECT COUNT(*) INTO n FROM ALL_TAB_COLS WHERE OWNER='LIMS_RUNTIME_LOCAL' AND TABLE_NAME='T_EMC_FOLDER' AND COLUMN_NAME='MONITORPOINTNAME' AND DATA_TYPE='VARCHAR2' AND DATA_LENGTH=300 AND NULLABLE='Y' AND HIDDEN_COLUMN='NO' AND VIRTUAL_COLUMN='NO' AND DATA_PRECISION IS NULL AND DATA_SCALE IS NULL AND DEFAULT_LENGTH IS NULL AND CHAR_USED='B' AND CHAR_LENGTH=300;
  IF n<>1 THEN RAISE_APPLICATION_ERROR(-20101,'Precondition mismatch T_EMC_FOLDER.MONITORPOINTNAME'); END IF;
  SELECT COUNT(*) INTO n FROM ALL_TAB_COLS WHERE OWNER='LIMS_RUNTIME_LOCAL' AND TABLE_NAME='T_CORE_FILE' AND COLUMN_NAME='SIZE' AND DATA_TYPE='NUMBER' AND DATA_LENGTH=22 AND NULLABLE='Y' AND HIDDEN_COLUMN='NO' AND VIRTUAL_COLUMN='NO' AND DATA_PRECISION=20 AND DATA_SCALE=0 AND DEFAULT_LENGTH IS NULL;
  IF n<>1 THEN RAISE_APPLICATION_ERROR(-20101,'Precondition mismatch T_CORE_FILE.SIZE'); END IF;
  SELECT COUNT(*) INTO n FROM ALL_TAB_COLS WHERE OWNER='LIMS_RUNTIME_LOCAL' AND TABLE_NAME='T_CORE_FILE' AND COLUMN_NAME='TIMES' AND DATA_TYPE='NUMBER' AND DATA_LENGTH=22 AND NULLABLE='N' AND HIDDEN_COLUMN='NO' AND VIRTUAL_COLUMN='NO' AND DATA_PRECISION=4 AND DATA_SCALE=0 AND DEFAULT_LENGTH IS NULL;
  IF n<>1 THEN RAISE_APPLICATION_ERROR(-20101,'Precondition mismatch T_CORE_FILE.TIMES'); END IF;
  SELECT COUNT(*) INTO n FROM ALL_TAB_COLS WHERE OWNER='LIMS_RUNTIME_LOCAL' AND TABLE_NAME='T_CORE_FILE' AND COLUMN_NAME='VERSION' AND DATA_TYPE='NUMBER' AND DATA_LENGTH=22 AND NULLABLE='Y' AND HIDDEN_COLUMN='NO' AND VIRTUAL_COLUMN='NO' AND DATA_PRECISION=20 AND DATA_SCALE=0 AND DEFAULT_LENGTH IS NULL;
  IF n<>1 THEN RAISE_APPLICATION_ERROR(-20101,'Precondition mismatch T_CORE_FILE.VERSION'); END IF;
  SELECT COUNT(*) INTO n FROM ALL_OBJECTS WHERE OWNER='LIMS_RUNTIME_LOCAL' AND OBJECT_NAME='T_EMC_EQUIPT_ACQ_FILE';
  IF n<>0 THEN RAISE_APPLICATION_ERROR(-20102,'Acquisition table already exists'); END IF;
  SELECT COUNT(*) INTO n FROM ALL_OBJECTS WHERE OWNER='LIMS_RUNTIME_LOCAL' AND OBJECT_NAME='IDX_CORE_ATRECORDLINE_TARGETID';
  IF n<>0 THEN RAISE_APPLICATION_ERROR(-20103,'Index name already exists'); END IF;
  SELECT COUNT(*) INTO n FROM ALL_OBJECTS WHERE OWNER='LIMS_RUNTIME_LOCAL' AND OBJECT_NAME='IDX_CORE_FILE_TARGET_BIZ_ID';
  IF n<>0 THEN RAISE_APPLICATION_ERROR(-20103,'Index name already exists'); END IF;
  SELECT COUNT(*) INTO n FROM ALL_OBJECTS WHERE OWNER='LIMS_RUNTIME_LOCAL' AND OBJECT_NAME='IDX_CORE_FILE_TARGET_ID';
  IF n<>0 THEN RAISE_APPLICATION_ERROR(-20103,'Index name already exists'); END IF;
  SELECT COUNT(*) INTO n FROM ALL_OBJECTS WHERE OWNER='LIMS_RUNTIME_LOCAL' AND OBJECT_NAME='IDX_CORE_FILE_TARGET_SCOPE_ID';
  IF n<>0 THEN RAISE_APPLICATION_ERROR(-20103,'Index name already exists'); END IF;
END;
/
ALTER TABLE "LIMS_RUNTIME_LOCAL"."T_CORE_AT_RECORD_LINE" MODIFY ("COLUMN" VARCHAR2(64 BYTE));
ALTER TABLE "LIMS_RUNTIME_LOCAL"."T_CORE_AT_RECORD_LINE" MODIFY ("CREATEDBYNAME" VARCHAR2(64 BYTE));
ALTER TABLE "LIMS_RUNTIME_LOCAL"."T_CORE_BPMN_COMMENT" MODIFY ("COMMENT" VARCHAR2(4000 BYTE));
ALTER TABLE "LIMS_RUNTIME_LOCAL"."T_CORE_FILE" MODIFY ("CREATEDBYNAME" VARCHAR2(64 BYTE));
ALTER TABLE "LIMS_RUNTIME_LOCAL"."T_CORE_FILE" MODIFY ("NAME" VARCHAR2(3000 BYTE));
ALTER TABLE "LIMS_RUNTIME_LOCAL"."T_CORE_FILE" MODIFY ("TARGETID" VARCHAR2(64 BYTE));
ALTER TABLE "LIMS_RUNTIME_LOCAL"."T_EMC_AUDIT_RECORD" MODIFY ("COMMENTS" VARCHAR2(4000 BYTE));
ALTER TABLE "LIMS_RUNTIME_LOCAL"."T_EMC_FOLDER" MODIFY ("MONITORPOINTNAME" VARCHAR2(900 BYTE));
ALTER TABLE "LIMS_RUNTIME_LOCAL"."T_CORE_FILE" MODIFY ("SIZE" NUMBER);
ALTER TABLE "LIMS_RUNTIME_LOCAL"."T_CORE_FILE" MODIFY ("TIMES" NUMBER);
ALTER TABLE "LIMS_RUNTIME_LOCAL"."T_CORE_FILE" MODIFY ("VERSION" NUMBER);
CREATE TABLE "LIMS_RUNTIME_LOCAL"."T_EMC_EQUIPT_ACQ_FILE"
   (	"ID" NUMBER(20,0) NOT NULL ENABLE,
	"EQUIPTID" NUMBER(20,0),
	"SOURCEFILENAME" VARCHAR2(270),
	"TARGETFILENAME" VARCHAR2(270),
	"CONTENT" CLOB,
	"RESULT" CLOB,
	"STATUS" NUMBER(20,0),
	"CREATEDTIME" DATE,
	"CREATEDBYORGNAME" VARCHAR2(270),
	 PRIMARY KEY ("ID")
  USING INDEX  ENABLE
   );
COMMENT ON COLUMN "LIMS_RUNTIME_LOCAL"."T_EMC_EQUIPT_ACQ_FILE"."CONTENT" IS '文件文本内容';
COMMENT ON COLUMN "LIMS_RUNTIME_LOCAL"."T_EMC_EQUIPT_ACQ_FILE"."CREATEDTIME" IS '制单时间';
COMMENT ON COLUMN "LIMS_RUNTIME_LOCAL"."T_EMC_EQUIPT_ACQ_FILE"."EQUIPTID" IS '仪器ID';
COMMENT ON COLUMN "LIMS_RUNTIME_LOCAL"."T_EMC_EQUIPT_ACQ_FILE"."ID" IS '主键';
COMMENT ON COLUMN "LIMS_RUNTIME_LOCAL"."T_EMC_EQUIPT_ACQ_FILE"."RESULT" IS '解析文件的字符串结果';
COMMENT ON COLUMN "LIMS_RUNTIME_LOCAL"."T_EMC_EQUIPT_ACQ_FILE"."SOURCEFILENAME" IS '源文件名称';
COMMENT ON COLUMN "LIMS_RUNTIME_LOCAL"."T_EMC_EQUIPT_ACQ_FILE"."STATUS" IS '处理状态0未处理，1已处理';
COMMENT ON COLUMN "LIMS_RUNTIME_LOCAL"."T_EMC_EQUIPT_ACQ_FILE"."TARGETFILENAME" IS '目录文件名称';
CREATE INDEX "LIMS_RUNTIME_LOCAL"."IDX_CORE_ATRECORDLINE_TARGETID" ON "LIMS_RUNTIME_LOCAL"."T_CORE_AT_RECORD_LINE" ("TARGETID");
CREATE INDEX "LIMS_RUNTIME_LOCAL"."IDX_CORE_FILE_TARGET_BIZ_ID" ON "LIMS_RUNTIME_LOCAL"."T_CORE_FILE" ("TARGETID", "BIZCATEGORY", "ID");
CREATE INDEX "LIMS_RUNTIME_LOCAL"."IDX_CORE_FILE_TARGET_ID" ON "LIMS_RUNTIME_LOCAL"."T_CORE_FILE" ("TARGETID", "ID");
CREATE INDEX "LIMS_RUNTIME_LOCAL"."IDX_CORE_FILE_TARGET_SCOPE_ID" ON "LIMS_RUNTIME_LOCAL"."T_CORE_FILE" ("TARGETID", "SCOPE", "ID");
EXIT;
